    fatigue_score SMALLINT,
    stress_score SMALLINT,
    readiness_score SMALLINT,
    sleep_quality_score SMALLINT,
    has_steps BOOLEAN NOT NULL,
    has_heart_rate BOOLEAN NOT NULL,
    has_sleep BOOLEAN NOT NULL,
    has_wellness BOOLEAN NOT NULL,
    warning_count BIGINT NOT NULL,
    quality_status VARCHAR NOT NULL,
    input_manifest_hash VARCHAR NOT NULL,
    rule_version VARCHAR NOT NULL,
    code_version VARCHAR NOT NULL,
    calculated_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (publication_id, participant_hk, local_date)
);

CREATE TABLE IF NOT EXISTS publication_build.participant_week (
    publication_id VARCHAR NOT NULL,
    participant_hk VARCHAR NOT NULL,
    study_hk VARCHAR NOT NULL,
    week_start DATE NOT NULL,
    expected_days BIGINT NOT NULL,
    expected_minutes BIGINT,
    accepted_steps_minutes BIGINT NOT NULL,
    accepted_heart_rate_minutes BIGINT NOT NULL,
    observed_steps_total DECIMAL(18,6),
    heart_rate_sum BIGINT,
    heart_rate_mean DECIMAL(18,6),
    accepted_sleep_sessions BIGINT NOT NULL,
    sleep_minutes_sum DECIMAL(18,6),
    sleep_minutes_mean DECIMAL(18,6),
    deep_sleep_pct_sum DECIMAL(18,6),
    deep_sleep_pct_count BIGINT NOT NULL,
    deep_sleep_pct_mean DECIMAL(18,6),
    efficiency_pct_sum DECIMAL(18,6),
    efficiency_pct_count BIGINT NOT NULL,
    efficiency_pct_mean DECIMAL(18,6),
    accepted_wellness_responses BIGINT NOT NULL,
    fatigue_sum DECIMAL(18,6),
    fatigue_count BIGINT NOT NULL,
    fatigue_mean DECIMAL(18,6),
    stress_sum DECIMAL(18,6),
    stress_count BIGINT NOT NULL,
    stress_mean DECIMAL(18,6),
    readiness_sum DECIMAL(18,6),
    readiness_count BIGINT NOT NULL,
    readiness_mean DECIMAL(18,6),
    sleep_quality_sum DECIMAL(18,6),
    sleep_quality_count BIGINT NOT NULL,
    sleep_quality_mean DECIMAL(18,6),
    warning_count BIGINT NOT NULL,
    partial_week BOOLEAN NOT NULL,
    quality_status VARCHAR NOT NULL,
    PRIMARY KEY (publication_id, participant_hk)
);

CREATE TABLE IF NOT EXISTS publication_build.sleep_stages (
    publication_id VARCHAR NOT NULL,
    session_version_id VARCHAR NOT NULL,
    stage_position BIGINT NOT NULL,
    sleep_session_hk VARCHAR NOT NULL,
    stage_type VARCHAR NOT NULL,
    start_at_utc TIMESTAMPTZ,
    end_at_utc TIMESTAMPTZ,
    duration_min_reported DECIMAL(18,6),
    is_post_boundary_awake BOOLEAN NOT NULL,
    warning_status VARCHAR,
    PRIMARY KEY (publication_id, session_version_id, stage_position)
);

CREATE TABLE IF NOT EXISTS publication_build.sleep_stage_exclusions (
    publication_id VARCHAR NOT NULL,
    session_version_id VARCHAR NOT NULL,
    stage_position BIGINT NOT NULL,
    reason_code VARCHAR NOT NULL,
    issue_id VARCHAR NOT NULL,
    resolution_id VARCHAR NOT NULL,
    PRIMARY KEY (publication_id, session_version_id, stage_position)
);

CREATE TABLE IF NOT EXISTS publication_build.requests (
    request_id VARCHAR NOT NULL,
    publication_id VARCHAR NOT NULL,
    scope_json JSON NOT NULL,
    PRIMARY KEY (request_id)
);

CREATE TABLE IF NOT EXISTS publication_build.inputs (
    publication_id VARCHAR NOT NULL,
    input_kind VARCHAR NOT NULL,
    version_id VARCHAR NOT NULL,
    source_relation VARCHAR NOT NULL,
    business_key_hash VARCHAR NOT NULL,
    payload_hash VARCHAR NOT NULL,
    PRIMARY KEY (publication_id, input_kind, version_id)
);

CREATE TABLE IF NOT EXISTS publication_build.readiness (
    publication_id VARCHAR NOT NULL,
    local_date DATE NOT NULL,
    revision BIGINT NOT NULL,
    input_manifest_hash VARCHAR NOT NULL,
    rule_version VARCHAR NOT NULL,
    code_version VARCHAR NOT NULL,
    coverage_json JSON NOT NULL,
    warning_counts_json JSON NOT NULL,
    PRIMARY KEY (publication_id, local_date)
);

CREATE TABLE IF NOT EXISTS publication_build.sleep_stage_candidates (
    publication_id VARCHAR NOT NULL,
    session_version_id VARCHAR NOT NULL,
    stage_position BIGINT NOT NULL,
    sleep_session_hk VARCHAR NOT NULL,
    stage_type VARCHAR NOT NULL,
    start_at_utc TIMESTAMPTZ,
    end_at_utc TIMESTAMPTZ,
    duration_min_reported DECIMAL(18,6),
    is_post_boundary_awake BOOLEAN NOT NULL,
    warning_status VARCHAR,
    PRIMARY KEY (publication_id, session_version_id, stage_position)
);

INSERT INTO business.quality_issue_statuses (code, display_name, description)
SELECT 'open', 'Open', 'The issue remains active and requires resolution.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_issue_statuses WHERE code = 'open');

INSERT INTO business.quality_issue_statuses (code, display_name, description)
SELECT 'resolved', 'Resolved', 'The issue was closed through an audited lifecycle transition.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_issue_statuses WHERE code = 'resolved');

INSERT INTO business.quality_severities (code, display_name, description)
SELECT 'error', 'Error', 'The record is rejected or conflicting and is excluded from accepted output.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_severities WHERE code = 'error');

INSERT INTO business.quality_severities (code, display_name, description)
SELECT 'warning', 'Warning', 'The record is accepted with a condition requiring review.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_severities WHERE code = 'warning');

INSERT INTO business.quality_severities (code, display_name, description)
SELECT 'pending', 'Pending', 'The record awaits an authoritative reference before acceptance.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_severities WHERE code = 'pending');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'reference_resolved', 'Reference resolved', 'The missing authoritative reference became available.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'reference_resolved');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'superseded_by_accepted_delta', 'Superseded by accepted delta', 'A later accepted upsert replaced the affected record.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'superseded_by_accepted_delta');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'source_deleted', 'Source deleted', 'An accepted explicit delete removed the current business key.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'source_deleted');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'rule_cleared', 'Rule cleared', 'The original issue condition no longer applies.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'rule_cleared');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'excluded_at_consolidation', 'Excluded at consolidation', 'A permitted terminal awake interval was excluded from a frozen publication.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'excluded_at_consolidation');

INSERT INTO business.quality_resolution_codes (code, display_name, description)
SELECT 'reopened', 'Reopened', 'A previously resolved issue became active again; its current status is open.'
WHERE NOT EXISTS (SELECT 1 FROM business.quality_resolution_codes WHERE code = 'reopened');

CREATE VIEW IF NOT EXISTS staging.stg_participants AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       json_extract_string(r.payload_json, '$.device_id') AS device_id,
       TRY_CAST(json_extract_string(r.payload_json, '$.age') AS SMALLINT) AS age_at_enrollment,
       TRY_CAST(json_extract_string(r.payload_json, '$.height_cm') AS DECIMAL(18,6)) AS height_cm,
       json_extract_string(r.payload_json, '$.gender') AS gender,
       json_extract_string(r.payload_json, '$.chronotype') AS chronotype,
       TRY_CAST(json_extract_string(r.payload_json, '$.max_heart_rate') AS SMALLINT) AS max_heart_rate
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'participants';

CREATE VIEW IF NOT EXISTS staging.stg_device_metadata AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       json_extract_string(r.payload_json, '$.device_id') AS device_id,
       json_extract_string(r.payload_json, '$.wear_site') AS wear_site,
       TRY_CAST(json_extract_string(r.payload_json, '$.calibration_date') AS DATE) AS calibration_date,
       json_extract_string(r.payload_json, '$.firmware_version') AS firmware_version_reported,
       json_extract_string(r.payload_json, '$.device_label') AS device_label
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'device_metadata';

CREATE VIEW IF NOT EXISTS staging.stg_steps AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       json_extract_string(r.payload_json, '$.timestamp') AS timestamp_original,
       TRY_CAST(json_extract_string(r.payload_json, '$.steps') AS BIGINT) AS steps_reported,
       json_extract_string(r.payload_json, '$._unit') AS unit_reported
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'steps';

CREATE VIEW IF NOT EXISTS staging.stg_heart_rate AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       json_extract_string(r.payload_json, '$.timestamp') AS timestamp_original,
       TRY_CAST(json_extract_string(r.payload_json, '$.heart_rate_bpm') AS BIGINT) AS heart_rate_bpm
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'heart_rate';

CREATE VIEW IF NOT EXISTS staging.stg_sleep_sessions AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       TRY_CAST(json_extract_string(r.payload_json, '$.date') AS DATE) AS wake_date,
       json_extract_string(r.payload_json, '$.sleep_onset') AS sleep_onset_original,
       json_extract_string(r.payload_json, '$.sleep_end') AS sleep_end_original,
       TRY_CAST(json_extract_string(r.payload_json, '$.efficiency_pct') AS DECIMAL(18,6)) AS efficiency_pct_reported,
       TRY_CAST(json_extract_string(r.payload_json, '$.restlessness') AS DECIMAL(18,6)) AS restlessness
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'sleep';

CREATE VIEW IF NOT EXISTS staging.stg_wellness AS
SELECT r.record_id,
       b.batch_id,
       b.delivery_sequence,
       b.source_system AS record_source,
       r.payload_json,
       r.ingested_at,
       COALESCE(json_extract_string(r.payload_json, '$._op'), 'upsert') AS operation,
       json_extract_string(r.payload_json, '$.participant_id') AS participant_id,
       TRY_CAST(json_extract_string(r.payload_json, '$.date') AS DATE) AS survey_date,
       TRY_CAST(json_extract_string(r.payload_json, '$.fatigue_score') AS SMALLINT) AS fatigue_score,
       TRY_CAST(json_extract_string(r.payload_json, '$.stress_score') AS SMALLINT) AS stress_score,
       TRY_CAST(json_extract_string(r.payload_json, '$.readiness_score') AS SMALLINT) AS readiness_score,
       TRY_CAST(json_extract_string(r.payload_json, '$.sleep_quality_score') AS SMALLINT) AS sleep_quality_score
FROM raw.source_records r JOIN raw.batch_records b ON b.record_id = r.record_id
WHERE r.source_name = 'wellness_survey';

CREATE VIEW IF NOT EXISTS staging.stg_sleep_stages AS
SELECT s.record_id AS session_record_id,
       s.batch_id,
       s.delivery_sequence,
       s.record_source,
       s.participant_id,
       s.wake_date,
       TRY_CAST(x.key AS BIGINT) AS stage_position,
       json_extract_string(x.value, '$.stage') AS stage_type,
       json_extract_string(x.value, '$.start_time') AS start_original,
       json_extract_string(x.value, '$.end_time') AS end_original,
       TRY_CAST(json_extract_string(x.value, '$.duration_min') AS DECIMAL(18,6)) AS duration_min_reported
FROM staging.stg_sleep_sessions s, LATERAL json_each(s.payload_json, '$.stages') x;

CREATE OR REPLACE VIEW analytics.dim_participant AS
SELECT * FROM marts.dim_participant;

CREATE OR REPLACE VIEW analytics.dim_device AS
SELECT * FROM marts.dim_device;

CREATE OR REPLACE VIEW analytics.dim_study AS
SELECT * FROM marts.dim_study;

CREATE OR REPLACE VIEW analytics.dim_date AS
SELECT * FROM marts.dim_date;

CREATE OR REPLACE VIEW analytics.gold_participant_devices AS
SELECT * FROM marts.gold_participant_devices;

CREATE OR REPLACE VIEW analytics.participant_day AS
SELECT d.* FROM marts.participant_day_current d
JOIN business.daily_publications p ON p.study_hk = d.study_hk AND p.local_date = d.local_date
AND p.input_manifest_hash = d.input_manifest_hash AND p.rule_version = d.rule_version AND p.code_version = d.code_version
WHERE p.status = 'published' AND p.published_at IS NOT NULL
AND d.quality_status IN ('accepted', 'accepted_with_warning');

CREATE OR REPLACE VIEW biostatistics.publications AS
SELECT * FROM publication_build.publications WHERE status = 'published' AND published_at IS NOT NULL;

CREATE OR REPLACE VIEW biostatistics.participant_snapshot AS
SELECT d.* FROM publication_build.participant_snapshot d
JOIN biostatistics.publications p ON p.publication_id = d.publication_id;

CREATE OR REPLACE VIEW biostatistics.participant_day AS
SELECT d.* FROM publication_build.participant_day d
JOIN biostatistics.publications p ON p.publication_id = d.publication_id;

CREATE OR REPLACE VIEW biostatistics.participant_week AS
SELECT d.* FROM publication_build.participant_week d
JOIN biostatistics.publications p ON p.publication_id = d.publication_id;

CREATE OR REPLACE VIEW biostatistics.sleep_stages AS
SELECT d.* FROM publication_build.sleep_stages d
JOIN biostatistics.publications p ON p.publication_id = d.publication_id;

CREATE OR REPLACE VIEW biostatistics.sleep_stage_exclusions AS
SELECT d.* FROM publication_build.sleep_stage_exclusions d
JOIN biostatistics.publications p ON p.publication_id = d.publication_id;

CREATE OR REPLACE VIEW biostatistics.latest_participant_week AS
SELECT d.* FROM biostatistics.participant_week d
JOIN (SELECT study_hk, week_start, MAX(revision) AS revision FROM biostatistics.publications
      GROUP BY study_hk, week_start) latest
ON latest.study_hk = d.study_hk AND latest.week_start = d.week_start
JOIN biostatistics.publications p ON p.publication_id = d.publication_id AND p.revision = latest.revision;

COMMIT;
